using Microsoft.EntityFrameworkCore;

namespace KarakusAluminyum.Web.Data;

public static class CrmSchemaInitializer
{
    public static async Task EnsureCreatedAsync(AppDbContext db)
    {
        await db.Database.ExecuteSqlRawAsync(SchemaSql);
    }

    private const string SchemaSql = """
-- Existing PostgreSQL installations: execute once against the application's database.
-- Fresh installations are created by EF Core EnsureCreated and don't need this script.
CREATE TABLE IF NOT EXISTS "Customers" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Name" character varying(160) NOT NULL,
  "Kind" integer NOT NULL DEFAULT 1,
  "Status" integer NOT NULL DEFAULT 0,
  "ContactPerson" character varying(120),
  "Email" character varying(180),
  "Phone" character varying(40),
  "TaxNumber" character varying(40),
  "TaxOffice" character varying(120),
  "Address" character varying(500),
  "City" character varying(100),
  "District" character varying(100),
  "Source" character varying(80),
  "Notes" character varying(2000),
  "CreatedUtc" timestamp with time zone NOT NULL,
  "UpdatedUtc" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_Customers_Name" ON "Customers" ("Name");
CREATE INDEX IF NOT EXISTS "IX_Customers_Phone" ON "Customers" ("Phone");
CREATE TABLE IF NOT EXISTS "Quotes" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "QuoteNumber" character varying(40) NOT NULL,
  "CustomerId" integer NOT NULL REFERENCES "Customers"("Id") ON DELETE RESTRICT,
  "Title" character varying(180) NOT NULL,
  "Status" integer NOT NULL DEFAULT 0,
  "CreatedUtc" timestamp with time zone NOT NULL,
  "ValidUntilUtc" timestamp with time zone,
  "Notes" character varying(2000),
  "TaxRate" numeric(5,2) NOT NULL DEFAULT 20,
  "DiscountRate" numeric(5,2) NOT NULL DEFAULT 0,
  "Subtotal" numeric(18,2) NOT NULL DEFAULT 0,
  "DiscountAmount" numeric(18,2) NOT NULL DEFAULT 0,
  "TaxAmount" numeric(18,2) NOT NULL DEFAULT 0,
  "GrandTotal" numeric(18,2) NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Quotes_QuoteNumber" ON "Quotes" ("QuoteNumber");
CREATE TABLE IF NOT EXISTS "QuoteItems" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "QuoteId" integer NOT NULL REFERENCES "Quotes"("Id") ON DELETE CASCADE,
  "Description" character varying(200) NOT NULL,
  "Quantity" numeric(18,3) NOT NULL DEFAULT 1,
  "Unit" character varying(20) NOT NULL DEFAULT 'Adet',
  "UnitPrice" numeric(18,2) NOT NULL DEFAULT 0,
  "LineTotal" numeric(18,2) NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS "IX_QuoteItems_QuoteId" ON "QuoteItems" ("QuoteId");

CREATE TABLE IF NOT EXISTS "AuditLogs" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ActorUserId" character varying(450) NOT NULL,
  "ActorEmail" character varying(256) NOT NULL,
  "Action" character varying(100) NOT NULL,
  "EntityType" character varying(100) NOT NULL,
  "EntityId" character varying(100),
  "Details" character varying(2000),
  "IpAddress" character varying(64),
  "CreatedUtc" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_AuditLogs_CreatedUtc" ON "AuditLogs" ("CreatedUtc");
CREATE INDEX IF NOT EXISTS "IX_AuditLogs_EntityType_EntityId" ON "AuditLogs" ("EntityType", "EntityId");

CREATE TABLE IF NOT EXISTS "GalleryImages" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "ServiceId" integer REFERENCES "Services"("Id") ON DELETE CASCADE,
  "ProjectId" integer REFERENCES "Projects"("Id") ON DELETE CASCADE,
  "ImagePath" character varying(500) NOT NULL,
  "Title" character varying(160),
  "Caption" character varying(500),
  "SortOrder" integer NOT NULL,
  "IsPublished" boolean NOT NULL,
  "CreatedUtc" timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_GalleryImages_ServiceId_SortOrder" ON "GalleryImages" ("ServiceId", "SortOrder");
CREATE INDEX IF NOT EXISTS "IX_GalleryImages_ProjectId_SortOrder" ON "GalleryImages" ("ProjectId", "SortOrder");

""";
}
